LOGO_B64 = ""

# ===================== D&K E-Technik – Video-Generator v2 =====================
# Usage: python3 dk_video.py episode.json out.mp4            -> video
#        python3 dk_video.py episode.json prefix preview     -> stills prefix_sceneN.jpg
# 1080x1920 30fps motion-graphics reel: scenes from JSON + fixed outro + procedurally
# composed music synced to the cuts. Look, motion and music vary per episode via
# episode["style"] = {"seed": int, optional "theme": name, "genre": name}.
import sys, os, io, json, base64, subprocess, math, wave, tempfile, zlib
import numpy as np
from PIL import Image, ImageDraw, ImageFont, ImageFilter, ImageChops

W, H, FPS = 1080, 1920, 30
BRAND = (247, 148, 29)
WHITE = (255, 255, 255)
# theme colours (overwritten by setup_style)
OR = BRAND
BG1, BG2 = (16, 16, 19), (30, 30, 36)
FG, GREY, DGREY = (255, 255, 255), (185, 185, 192), (120, 120, 128)
ACC2 = (70, 200, 255)
PANEL, PANEL2, LINEC = (42, 42, 50), (60, 60, 68), (40, 40, 47)
LIGHT = False
FD = "/usr/share/fonts/opentype/inter/"
EMOJI = "/usr/share/fonts/truetype/noto/NotoColorEmoji.ttf"
_fc = {}
def font(kind, size):
    k = (kind, size)
    if k not in _fc:
        _fc[k] = ImageFont.truetype(FD + {"xb": "Inter-ExtraBold.otf", "b": "Inter-Bold.otf", "sb": "Inter-SemiBold.otf"}[kind], size)
    return _fc[k]

def ease(x):
    x = max(0.0, min(1.0, x)); return 1 - (1 - x) ** 3
def back(x):
    x = max(0.0, min(1.0, x)); c = 1.9; return 1 + (c + 1) * (x - 1) ** 3 + c * (x - 1) ** 2
def mix(a, b, t):
    return tuple(int(x + (y - x) * t) for x, y in zip(a, b))
def de(n, dec=0):
    s = f"{n:,.{dec}f}" if dec else f"{int(round(n)):,}"
    return s.replace(",", "X").replace(".", ",").replace("X", ".")

# ---------- style system ----------
THEMES = {
    "navy":    dict(bg1=(8, 16, 38), bg2=(20, 40, 82), fg=(255, 255, 255), sub=(178, 192, 218), acc=(247, 148, 29), acc2=(70, 200, 255), motif="blueprint", light=False),
    "hell":    dict(bg1=(250, 248, 244), bg2=(232, 227, 218), fg=(24, 24, 30), sub=(88, 88, 100), acc=(240, 132, 10), acc2=(20, 120, 140), motif="shapes", light=True),
    "petrol":  dict(bg1=(3, 34, 40), bg2=(8, 72, 72), fg=(255, 255, 255), sub=(172, 214, 208), acc=(247, 148, 29), acc2=(110, 230, 160), motif="waves", light=False),
    "violett": dict(bg1=(20, 8, 42), bg2=(64, 18, 90), fg=(255, 255, 255), sub=(208, 188, 232), acc=(255, 150, 40), acc2=(255, 80, 170), motif="synth", light=False),
    "graphit": dict(bg1=(24, 24, 26), bg2=(58, 54, 46), fg=(255, 255, 255), sub=(208, 202, 190), acc=(247, 148, 29), acc2=(255, 208, 40), motif="stripes", light=False),
    "sand":    dict(bg1=(255, 242, 226), bg2=(248, 214, 176), fg=(44, 26, 12), sub=(108, 78, 54), acc=(222, 98, 8), acc2=(18, 92, 122), motif="halftone", light=True),
}
THEME_ORDER = ["navy", "hell", "petrol", "violett", "graphit", "sand"]
GENRES = ["house", "hiphop", "futurebass", "synthwave", "afro", "dnb", "techno"]
BPM_RANGE = {"house": (120, 124), "hiphop": (86, 94), "futurebass": (140, 150), "synthwave": (100, 110),
             "afro": (110, 118), "dnb": (170, 174), "techno": (124, 128)}
PROGS_MIN = [[0, 5, 2, 6], [0, 3, 4, 4], [0, 6, 5, 6], [0, 2, 3, 4], [0, 5, 3, 4]]
PROGS_MAJ = [[0, 4, 5, 3], [0, 5, 3, 4], [3, 4, 0, 5], [0, 3, 5, 4], [5, 3, 0, 4]]
TRANSITIONS = ["iris", "bolt", "diag", "shutter", "whip", "zoom", "glitch"]
STYLE = {}

def setup_style(ep):
    """Derive the full look + music parameters for this episode from its style seed."""
    global OR, BG1, BG2, FG, GREY, DGREY, ACC2, PANEL, PANEL2, LINEC, LIGHT, BG_ARR, _ORANGE
    st = dict(ep.get("style", {}))
    seed = int(st.get("seed", zlib.crc32(ep.get("topic", "dk").encode()) % 1000))
    rng = np.random.default_rng(seed * 7919 + 17)
    theme = st.get("theme") or THEME_ORDER[seed % len(THEME_ORDER)]
    genre = st.get("genre") or GENRES[seed % len(GENRES)]
    th = THEMES[theme]
    OR, BG1, BG2, FG, GREY, ACC2, LIGHT = th["acc"], th["bg1"], th["bg2"], th["fg"], th["sub"], th["acc2"], th["light"]
    DGREY = mix(BG2, GREY, 0.85)
    PANEL = mix(BG2, FG, 0.10 if not LIGHT else 0.07)
    PANEL2 = mix(BG2, FG, 0.18 if not LIGHT else 0.12)
    LINEC = mix(BG1, FG, 0.10 if not LIGHT else 0.08)
    BG_ARR = _bg()
    _ORANGE = None
    lo, hi = BPM_RANGE[genre]
    minor = bool(rng.random() < (0.7 if genre in ("techno", "dnb", "synthwave", "futurebass") else 0.45))
    tr = list(rng.permutation(TRANSITIONS)[:3])
    STYLE.clear()
    STYLE.update(dict(
        seed=seed, theme=theme, genre=genre, motif=th["motif"],
        bpm=int(rng.integers(lo, hi + 1)), key=int(rng.integers(43, 51)), minor=minor,
        prog=[int(x) for x in (PROGS_MIN if minor else PROGS_MAJ)[int(rng.integers(0, 5))]],
        trans=tr, text_mode=str(rng.choice(["pop", "rise", "drop", "slam"])),
        hook_mode=str(rng.choice(["slam", "drop", "pop"])),
        mirror=bool(rng.random() < 0.5), moves=[str(m) for m in rng.choice(["push", "pull", "drift", "tilt"], 8)],
        punch=float(rng.uniform(0.010, 0.018)), particles=bool(rng.random() < 0.7),
        circuits=bool(theme in ("navy", "graphit") or rng.random() < 0.3),
        item_emoji=str(rng.choice(["✅", "⚡", "👉", "✔️"])), drop=0.0, end=99.0, brk=(0.0, 0.0),
    ))
    return STYLE

def beat_pulse(gt):
    """0..1 envelope that spikes on the music's kicks (only in full sections)."""
    if not STYLE or gt < STYLE["drop"] or gt >= STYLE["end"]: return 0.0
    b0, b1 = STYLE["brk"]
    if b0 <= gt < b1: return 0.0
    B = 60.0 / STYLE["bpm"]
    k = (gt - STYLE["drop"]) / B
    if STYLE["genre"] in ("hiphop", "futurebass", "dnb"):
        if int(math.floor(k)) % 2: return 0.0
    return math.exp(-(k % 1.0) * 7.0)

