_ef = None
_ecache = {}
def emoji(ch, size):
    global _ef
    if (ch, size) in _ecache: return _ecache[(ch, size)]
    if _ef is None: _ef = ImageFont.truetype(EMOJI, 109)
    im = Image.new("RGBA", (160, 160))
    ImageDraw.Draw(im).text((10, 10), ch, font=_ef, embedded_color=True)
    im = im.crop(im.getbbox() or (0, 0, 160, 160))
    s = size / max(im.size)
    im = im.resize((max(1, int(im.width * s)), max(1, int(im.height * s))), Image.LANCZOS)
    _ecache[(ch, size)] = im
    return im

def _bg():
    y = np.linspace(0, 1, H)[:, None, None]
    x = np.linspace(0, 1, W)[None, :, None]
    g = np.array(BG1) * (1 - y) + np.array(BG2) * y
    g = g + (x - 0.5) * 10 * (1 if not LIGHT else -1)
    return np.clip(np.repeat(g, 1, axis=1) * np.ones((1, W, 1)), 0, 255).astype(np.uint8)
BG_ARR = _bg()
_glow = Image.new("L", (1400, 1400), 0)
ImageDraw.Draw(_glow).ellipse([420, 420, 980, 980], fill=75)
_glow = _glow.filter(ImageFilter.GaussianBlur(170))

def wrap(d, text, f, maxw):
    out = []
    for para in text.split("\n"):
        line = ""
        for w in para.split(" "):
            if not w: continue
            test = (line + " " + w).strip()
            if d.textlength(test, font=f) <= maxw or not line: line = test
            else: out.append(line); line = w
        out.append(line)
    return out


# ---------- motion fx ----------
_prng = np.random.default_rng(11)
PARTS = [dict(x=_prng.random() * W, y=_prng.random() * H, z=0.25 + _prng.random() * 0.75,
              s=_prng.random() * 6.28, k=int(_prng.integers(0, 4))) for _ in range(26)]

def particles(d, gt):
    pu = beat_pulse(gt)
    for p in PARTS:
        z = p["z"]
        y = (p["y"] - gt * 110 * z) % (H + 100) - 50
        x = p["x"] + 40 * math.sin(gt * 0.7 + p["s"]) * z
        r = 2 + 5 * z + 3 * pu * z
        c = mix(BG1, OR if p["k"] % 2 else ACC2, 0.2 + 0.5 * z) if p["k"] else mix(BG1, FG, 0.08 + 0.25 * z)
        d.ellipse([x - r, y - r, x + r, y + r], fill=c)

def rings(d, gt, cx, cy, R, seed=0):
    for k in range(3):
        a0 = (gt * (38 + 12 * k) * (1 if k % 2 else -1) + k * 80 + seed) % 360
        rr = R + k * 42
        d.arc([cx - rr, cy - rr, cx + rr, cy + rr], a0, a0 + 100 + k * 35,
              fill=mix(BG1, OR if k != 1 else ACC2, 0.42 - 0.1 * k), width=7 - 2 * k)

# ---------- background motifs ----------
def motif(img, d, gt):
    m = STYLE.get("motif", "blueprint"); pu = beat_pulse(gt)
    if m == "blueprint":
        off = (gt * 18) % 90
        for i in range(-1, H // 90 + 2):
            y = int(i * 90 + off)
            d.line([(0, y), (W, y)], fill=mix(BG1, ACC2, 0.10 if i % 3 else 0.18), width=1 if i % 3 else 2)
        for j in range(0, W // 90 + 2):
            x = int(j * 90)
            d.line([(x, 0), (x, H)], fill=mix(BG1, ACC2, 0.10 if j % 3 else 0.18), width=1 if j % 3 else 2)
    elif m == "shapes":
        for k in range(6):
            cx = W * (0.15 + 0.7 * ((k * 0.37 + 0.05 * math.sin(gt * 0.4 + k)) % 1))
            cy = H * ((k * 0.23 + gt * 0.015 * (1 + k % 3)) % 1.1) - 60
            r = 120 + 60 * (k % 3) + 10 * pu
            col = mix(BG1, OR if k % 2 else ACC2, 0.10 + 0.04 * pu)
            if k % 3 == 0: d.ellipse([cx - r, cy - r, cx + r, cy + r], fill=col)
            elif k % 3 == 1: d.rounded_rectangle([cx - r, cy - r, cx + r, cy + r], int(r * 0.35), fill=col)
            else: d.ellipse([cx - r, cy - r, cx + r, cy + r], outline=col, width=18)
    elif m == "waves":
        for k in range(6):
            y0 = 260 + k * 300
            pts = [(x, y0 + 40 * math.sin(x / 170 + gt * (1.1 + 0.2 * k) + k) + 20 * math.sin(x / 61 - gt * 1.7)) for x in range(-20, W + 40, 30)]
            d.line(pts, fill=mix(BG1, ACC2 if k % 2 else OR, 0.16 + 0.12 * pu), width=4 + (k % 2) * 3, joint="curve")
    elif m == "synth":
        hy = 1180
        d.ellipse([W / 2 - 300, hy - 300, W / 2 + 300, hy + 300], fill=mix(BG2, OR, 0.10 + 0.05 * pu))
        d.rectangle([0, hy, W, H], fill=mix(BG1, BG2, 0.6))
        for i in range(1, 16):
            q = ((i + (gt * 1.6) % 1) / 15.0) ** 2.2
            y = hy + q * (H - hy)
            d.line([(0, y), (W, y)], fill=mix(BG1, ACC2, 0.12 + 0.25 * q), width=2 + int(3 * q))
        for j in range(-8, 9):
            d.line([(W / 2 + j * 40, hy), (W / 2 + j * 260, H)], fill=mix(BG1, ACC2, 0.22), width=2)
    elif m == "stripes":
        off = (gt * 60) % 120
        for k in range(-20, 30):
            x = k * 120 + off
            d.polygon([(x, 0), (x + 40, 0), (x + 40 - H * 0.4, H), (x - H * 0.4, H)], fill=mix(BG1, BG2, 0.55))
        d.rectangle([0, H - 120, W, H - 70], fill=mix(BG1, ACC2, 0.18))
    elif m == "halftone":
        for yy in range(30, H, 60):
            for xx in range(30 + (yy // 60 % 2) * 30, W, 60):
                v = 0.5 + 0.5 * math.sin(xx / 210 + yy / 300 - gt * 1.3)
                r = 2 + 9 * v * v + 2 * pu
                d.ellipse([xx - r, yy - r, xx + r, yy + r], fill=mix(BG1, OR, 0.10 + 0.12 * v))

_wcache = {}
def _word_img(word, f, col):
    key = (word, f.path if hasattr(f, "path") else id(f), f.size, col)
    if key not in _wcache:
        w = int(f.getlength(word)) + 12
        h = int(f.size * 1.35)
        im = Image.new("RGBA", (w, h), (0, 0, 0, 0))
        ImageDraw.Draw(im).text((6, 0), word, font=f, fill=col)
        _wcache[key] = im
    return _wcache[key]

def kinetic(img, lines, f, y0, lh, t, delay, col=None, mode=None, stagger=0.07):
    col = FG if col is None else col
    mode = mode or STYLE.get("text_mode", "pop")
    d = ImageDraw.Draw(img)
    sp = d.textlength(" ", font=f)
    k = 0
    for i, ln in enumerate(lines):
        words = [w for w in ln.split(" ") if w]
        widths = [d.textlength(w, font=f) for w in words]
        x = (W - (sum(widths) + sp * (len(words) - 1))) / 2
        y = y0 + i * lh
        for w, ww in zip(words, widths):
            tt = (t - delay - k * stagger) / 0.42
            k += 1
            if tt > 0:
                wi = _word_img(w, f, col)
                if tt >= 1:
                    img.paste(wi, (int(x) - 6, int(y)), wi)
                else:
                    dy = 0
                    if mode == "slam":
                        s = 1 + 0.55 * (1 - ease(tt)); a = min(1.0, tt * 3.5)
                    elif mode == "rise":
                        s = 1.0; a = min(1.0, tt * 2.0); dy = (1 - ease(tt)) * 70
                    elif mode == "drop":
                        s = 1.0; a = min(1.0, tt * 3.0); dy = -(1 - back(tt)) * 120
                    else:
                        s = max(0.05, back(tt)); a = min(1.0, tt * 2.5); dy = (1 - min(1.0, tt)) * 40
                    im2 = wi.resize((max(1, int(wi.width * s)), max(1, int(wi.height * s))), Image.BILINEAR) if s != 1.0 else wi.copy()
                    if a < 1:
                        al = im2.getchannel("A").point(lambda v, a=a: int(v * a)); im2.putalpha(al)
                    cx = x + ww / 2
                    cy = y + wi.height / 2 + dy
                    img.paste(im2, (int(cx - im2.width / 2), int(cy - im2.height / 2)), im2)
            x += ww + sp
    return y0 + len(lines) * lh

def burst(d, cx, cy, t, t0, n=14, R=260, col=None):
    col = OR if col is None else col
    q = (t - t0) / 0.7
    if not 0 < q < 1: return
    e = ease(q)
    for i in range(n):
        a = 2 * math.pi * i / n
        r1, r2 = R * 0.3 + R * e, R * 0.3 + R * e + 60 * (1 - q)
        d.line([(cx + r1 * math.cos(a), cy + r1 * math.sin(a)), (cx + r2 * math.cos(a), cy + r2 * math.sin(a))],
               fill=mix(BG2, col, 1 - q), width=max(1, int(10 * (1 - q))))

_crng = np.random.default_rng(5)
CONF = [(_crng.uniform(-1, 1), _crng.uniform(-1.4, -0.4), _crng.uniform(0, 6.28), _crng.integers(0, 3)) for _ in range(46)]
def confetti(d, cx, cy, t, t0):
    q = t - t0
    if not 0 < q < 2.6: return
    for vx, vy, rot, c in CONF:
        x = cx + vx * 900 * q
        y = cy + vy * 1300 * q + 1500 * q * q
        a = rot + q * 9
        sz = 14
        pts = [(x + sz * math.cos(a + k * math.pi / 2) * (1 if k % 2 else 0.5), y + sz * math.sin(a + k * math.pi / 2) * (1 if k % 2 else 0.5)) for k in range(4)]
        d.polygon(pts, fill=[OR, ACC2, (255, 200, 90)][int(c)])

def camera(img, z, dx, dy):
    if z <= 1.0005 and abs(dx) < 0.5 and abs(dy) < 0.5: return img
    cw, ch = W / z, H / z
    x0 = (W - cw) / 2 + dx; y0 = (H - ch) / 2 + dy
    return img.crop((int(x0), int(y0), int(x0 + cw), int(y0 + ch))).resize((W, H), Image.BILINEAR)


# ---------- electric fx: circuit traces, lightning, transitions ----------
_trng = np.random.default_rng(23)
def _make_trace():
    side = int(_trng.integers(0, 4))
    if side == 0: x, y, dirs = float(_trng.uniform(80, W - 80)), -20.0, [(0, 1), (1, 1), (-1, 1)]
    elif side == 1: x, y, dirs = float(_trng.uniform(80, W - 80)), H + 20.0, [(0, -1), (1, -1), (-1, -1)]
    elif side == 2: x, y, dirs = -20.0, float(_trng.uniform(200, H - 200)), [(1, 0), (1, 1), (1, -1)]
    else: x, y, dirs = W + 20.0, float(_trng.uniform(200, H - 200)), [(-1, 0), (-1, 1), (-1, -1)]
    pts = [(x, y)]
    for i in range(int(_trng.integers(3, 6))):
        dx, dy = dirs[0] if i % 2 == 0 else dirs[int(_trng.integers(1, 3))]
        L = float(_trng.uniform(90, 230))
        n = math.hypot(dx, dy)
        x += dx / n * L; y += dy / n * L
        pts.append((x, y))
    return pts
TRACES = [_make_trace() for _ in range(16)]
def _trace_len(pts):
    return [math.dist(pts[i], pts[i + 1]) for i in range(len(pts) - 1)]
TRACE_LENS = [_trace_len(tp) for tp in TRACES]
def _point_on(pts, lens, dist):
    for i, L in enumerate(lens):
        if dist <= L:
            f = dist / L if L else 0
            return (pts[i][0] + (pts[i + 1][0] - pts[i][0]) * f, pts[i][1] + (pts[i + 1][1] - pts[i][1]) * f)
        dist -= L
    return pts[-1]

def circuits(d, gt):
    for k, (pts, lens) in enumerate(zip(TRACES, TRACE_LENS)):
        d.line(pts, fill=LINEC, width=3, joint="curve")
        ex, ey = pts[-1]
        d.ellipse([ex - 7, ey - 7, ex + 7, ey + 7], outline=mix(LINEC, FG, 0.06), width=3)
        total = sum(lens)
        u = ((gt * (0.32 + 0.05 * (k % 4)) + k * 0.37) % 1.8)
        if u < 1.0:
            head = u * total
            seg = [_point_on(pts, lens, max(0.0, head - j * 14)) for j in range(7)]
            d.line(seg, fill=mix(BG1, OR, 0.45), width=9)
            d.line(seg[:4], fill=(255, 196, 110), width=4)
            hx, hy = seg[0]
            d.ellipse([hx - 5, hy - 5, hx + 5, hy + 5], fill=(255, 236, 190))
        elif u < 1.25:
            g = 1 - (u - 1.0) / 0.25
            d.ellipse([ex - 12, ey - 12, ex + 12, ey + 12], fill=mix(BG1, OR, 0.8 * g))

BOLT = [(0.18, -1.0), (-0.42, 0.12), (-0.02, 0.12), (-0.2, 1.0), (0.42, -0.14), (0.02, -0.14)]
def bolt_mask(scale, cx=W / 2, cy=H / 2):
    m = Image.new("L", (W, H), 0)
    ImageDraw.Draw(m).polygon([(cx + x * scale, cy + y * scale) for x, y in BOLT], fill=255)
    return m

_ORANGE = None
def _cover():
    global _ORANGE
    if _ORANGE is None: _ORANGE = Image.new("RGB", (W, H), OR)
    return _ORANGE

def _poly_mask(pts):
    m = Image.new("L", (W, H), 0); ImageDraw.Draw(m).polygon(pts, fill=255); return m

def transition(kind, img, t, dur, has_in, has_out):
    """Scene transitions. Every scene ends covered / starts uncovering so cuts stay seamless."""
    TI, TO = 0.40, 0.30
    qi = t / TI if (has_in and t < TI) else None
    qo = (t - (dur - TO)) / TO if (has_out and t > dur - TO) else None
    C = _cover()
    if kind == "bolt":
        if qi is not None: img = Image.composite(img, C, bolt_mask(30 + ease(qi) ** 1.6 * 5200))
        if qo is not None: img = Image.composite(C, img, bolt_mask(20 + (qo ** 2.2) * 5200))
    elif kind == "iris":
        R = math.hypot(W, H) / 2 + 20
        for q, inv in ((qi, False), (qo, True)):
            if q is None: continue
            r = (ease(q) if not inv else q ** 2) * R
            m = Image.new("L", (W, H), 0); ImageDraw.Draw(m).ellipse([W / 2 - r, H / 2 - r, W / 2 + r, H / 2 + r], fill=255)
            img = Image.composite(img, C, m) if not inv else Image.composite(C, img, m)
    elif kind == "diag":
        S = W + H * 0.5
        if qi is not None:
            x = ease(qi) * S
            img = Image.composite(C, img, _poly_mask([(x, 0), (S + 40, 0), (S + 40, H), (x - H * 0.5, H)]))
        if qo is not None:
            x = (qo ** 1.8) * S
            img = Image.composite(C, img, _poly_mask([(-H * 0.5 - 40, 0), (x, 0), (x - H * 0.5, H), (-H * 0.5 - 40, H)]))
    elif kind == "shutter":
        n = 8; bh = H / n
        for q, inv in ((qi, False), (qo, True)):
            if q is None: continue
            m = Image.new("L", (W, H), 0); dm = ImageDraw.Draw(m)
            for k in range(n):
                qq = max(0.0, min(1.0, q * 1.6 - k * 0.06 * (1 if not inv else 1)))
                h = bh * ((1 - ease(qq)) if not inv else ease(qq))
                dm.rectangle([0, k * bh + (bh - h) / 2, W, k * bh + (bh + h) / 2], fill=255)
            img = Image.composite(C, img, m)
    elif kind == "whip":
        for q, sgn in ((qi, 1), (qo, -1)):
            if q is None: continue
            off = (1 - ease(q)) * W * 0.9 if sgn == 1 else -(q ** 2) * W * 0.9
            base_ = Image.new("RGB", (W, H), BG1)
            acc = None
            for s in range(4):
                b2 = base_.copy(); b2.paste(img, (int(off + sgn * s * 22 * (1 - (q if sgn == 1 else 1 - q))), 0))
                acc = b2 if acc is None else Image.blend(acc, b2, 1.0 / (s + 1))
            img = acc
    elif kind == "zoom":
        if qi is not None:
            z = 1 + 0.35 * (1 - ease(qi)); img = camera(img, z, 0, 0)
            if qi < 0.7: img = img.filter(ImageFilter.GaussianBlur(14 * (1 - qi / 0.7)))
            img = Image.blend(img, C, max(0.0, 0.8 * (1 - qi * 2.2)))
        if qo is not None:
            z = 1 + 0.45 * qo ** 2; img = camera(img, z, 0, 0)
            img = img.filter(ImageFilter.GaussianBlur(12 * qo))
            img = Image.blend(img, C, min(1.0, qo ** 1.5))
    elif kind == "glitch":
        q = qi if qi is not None else (1 - qo if qo is not None else None)
        if q is not None:
            amt = (1 - q)
            r, g, b = img.split()
            sh = int(40 * amt)
            r = ImageChops.offset(r, sh, 0); b = ImageChops.offset(b, -sh, int(10 * amt))
            img = Image.merge("RGB", (r, g, b))
            rnd = np.random.default_rng(int(t * 1000))
            for _ in range(int(10 * amt)):
                y = int(rnd.integers(0, H - 80)); hh = int(rnd.integers(20, 120))
                strip = img.crop((0, y, W, y + hh)); img.paste(strip, (int(rnd.integers(-120, 120)), y))
            if qo is not None and qo > 0.6:
                img = Image.blend(img, C, (qo - 0.6) / 0.4)
            if qi is not None and qi < 0.25:
                img = Image.blend(img, C, 1 - qi / 0.25)
    return img

def flash(img, t, events, strength=0.3):
    a = 0.0
    for e in events:
        if 0 <= t - e < 0.18:
            a = max(a, strength * (1 - (t - e) / 0.18))
    if a > 0.01:
        img = Image.blend(img, Image.new("RGB", (W, H), (255, 244, 220)), a)
    return img

# ---------- shared chrome ----------
RING_AT = None
def base(t, gt, total, show_logo=True):
    img = Image.fromarray(BG_ARR.copy())
    gx = int(W * 0.5 + 330 * math.sin(gt * 0.45)) - 450
    gy = int(H * 0.42 + 260 * math.cos(gt * 0.33)) - 450
    gcol = OR if not LIGHT else mix(BG1, OR, 0.6)
    img.paste(Image.new("RGB", (1400, 1400), gcol), (gx - 250, gy - 250), _glow)
    gx2 = int(W * 0.5 - 360 * math.sin(gt * 0.3 + 1)) - 450
    gy2 = int(H * 0.7 + 200 * math.sin(gt * 0.27)) - 450
    img.paste(Image.new("RGB", (1400, 1400), mix(BG1, ACC2, 0.7)), (gx2 - 250, gy2 - 250), _glow)
    d = ImageDraw.Draw(img)
    motif(img, d, gt)
    if STYLE.get("circuits", True): circuits(d, gt)
    if STYLE.get("particles", True): particles(d, gt)
    if RING_AT is not None:
        rings(d, gt, RING_AT[0], RING_AT[1], RING_AT[2], int(gt))
    if show_logo:
        card = Image.new("RGB", (360, 120), WHITE); card.paste(_LOGO_SMALL, (30, (120 - _LOGO_SMALL.height) // 2))
        m = Image.new("L", card.size, 0); ImageDraw.Draw(m).rounded_rectangle([0, 0, 359, 119], 22, fill=255)
        if LIGHT:
            d.rounded_rectangle([(W - 360) // 2 - 3, 87, (W + 360) // 2 + 2, 212], 24, fill=mix(BG1, FG, 0.15))
        img.paste(card, ((W - 360) // 2, 90), m)
    return img, d

def progress(img, gt, total):
    d = ImageDraw.Draw(img)
    d.rectangle([0, H - 14, W, H], fill=PANEL)
    d.rectangle([0, H - 14, int(W * min(1, gt / total)), H], fill=OR)
    return img

def wipe_in(img, t):
    return img

def kicker(d, txt, y, t, delay=0.15):
    a = ease((t - delay) / 0.4)
    f = font("xb", 42)
    tw = d.textlength(txt, font=f)
    x = (W - tw) / 2
    d.rounded_rectangle([x - 28, y - 12, x + tw + 28, y + 60], 36, fill=mix(BG1, OR, a))
    d.text((x, y), txt, font=f, fill=mix(OR, (20, 16, 12) if not LIGHT else WHITE, a) if not LIGHT else mix(OR, WHITE, a))

def lines_anim(d, lines, f, y0, lh, t, delay, col=None, stagger=0.12):
    col = FG if col is None else col
    for i, ln in enumerate(lines):
        a = ease((t - delay - i * stagger) / 0.45)
        if a <= 0: continue
        tw = d.textlength(ln, font=f)
        d.text(((W - tw) / 2, y0 + i * lh + (1 - a) * 50), ln, font=f, fill=mix(BG2, col, a))
    return y0 + len(lines) * lh

def paste_emoji(img, ch, size, cx, cy, t, delay=0.2):
    p = back((t - delay) / 0.5)
    if p <= 0.02: return
    s = int(size * p)
    bob = int(10 * math.sin(t * 2.4))
    e = emoji(ch, s)
    img.paste(e, (cx - e.width // 2, cy - e.height // 2 + bob), e)

# ---------- Maskottchen: Glühbirne mit Bauhelm (eigene Figur von D&K) ----------
_SS = 2
_CW, _CH = 600, 620           # local canvas
_OX, _OY = 90, 30             # translate local design coords
_GLASS_ON = (255, 214, 92)
_GLASS_OFF = (214, 214, 200)
_LINE = (43, 30, 16)
_HELM = OR
_GREY1, _GREY2 = (170, 172, 178), (128, 130, 138)
_LIMB = (196, 108, 30)
_BOOT = (110, 112, 122)

def _P(x, y):
    return ((x + _OX) * _SS, (y + _OY) * _SS)

def _R(x0, y0, x1, y1):
    a, b = _P(x0, y0), _P(x1, y1)
    return [a[0], a[1], b[0], b[1]]

_mglow_sprite = None
def _mglow():
    global _mglow_sprite
    if _mglow_sprite is None:
        g = Image.new("L", (_CW * _SS, _CH * _SS), 0)
        ImageDraw.Draw(g).ellipse(_R(30, 30, 390, 390), fill=120)
        _mglow_sprite = g.filter(ImageFilter.GaussianBlur(36 * _SS))
    return _mglow_sprite

def _arm(d, sx, sy, a1, a2, hand="open", lw=15):
    r1, r2 = math.radians(a1), math.radians(a2)
    ex, ey = sx + 78 * math.cos(r1), sy + 78 * math.sin(r1)
    hx, hy = ex + 66 * math.cos(r2), ey + 66 * math.sin(r2)
    d.line([_P(sx, sy), _P(ex, ey), _P(hx, hy)], fill=_LIMB, width=lw * _SS, joint="curve")
    d.ellipse(_R(ex - lw / 2, ey - lw / 2, ex + lw / 2, ey + lw / 2), fill=_LIMB)
    if hand == "thumb":
        d.rounded_rectangle(_R(hx - 10, hy - 62, hx + 12, hy - 4), 11 * _SS, fill="white", outline=_LINE, width=5 * _SS)
    d.ellipse(_R(hx - 25, hy - 25, hx + 25, hy + 25), fill="white", outline=_LINE, width=6 * _SS)
    if hand == "point":
        d.rounded_rectangle(_R(hx + 10 * math.cos(r2) - 8, hy + 10 * math.sin(r2) - 8,
                               hx + 40 * math.cos(r2) + 8, hy + 40 * math.sin(r2) + 8), 8 * _SS,
                            fill="white", outline=_LINE, width=5 * _SS)
        d.ellipse(_R(hx - 21, hy - 21, hx + 21, hy + 21), fill="white")

def _star(d, cx, cy, r, col):
    pts = []
    for i in range(8):
        a = math.pi / 4 * i - math.pi / 2
        rr = r if i % 2 == 0 else r * 0.32
        pts.append(_P(cx + rr * math.cos(a), cy + rr * math.sin(a)))
    d.polygon(pts, fill=col)

POSES = {
    "idle":   lambda t: ((112 + 4 * math.sin(t * 2), 100), (68 - 4 * math.sin(t * 2), 80), "open", "open"),
    "wave":   lambda t: ((112, 100), (-35, -80 + 28 * math.sin(t * 9)), "open", "open"),
    "point":  lambda t: ((112, 100), (-8, -14 + 4 * math.sin(t * 5)), "open", "point"),
    "pointdown": lambda t: ((112, 100), (25, 60 + 5 * math.sin(t * 5)), "open", "point"),
    "thumb":  lambda t: ((112, 100), (20, -72 + 3 * math.sin(t * 6)), "open", "thumb"),
    "cheer":  lambda t: ((-128 + 8 * math.sin(t * 12), -104), (-52 - 8 * math.sin(t * 12), -76), "open", "open"),
    "worried": lambda t: ((150, -150 + 6 * math.sin(t * 7)), (30, -30 - 6 * math.sin(t * 7)), "open", "open"),
}

def draw_mascot(height, t, pose="idle", expr="smile", lit=True, look=(0, 0), extra=0.0):
    """Returns RGBA image of the mascot, `height` px tall."""
    im = Image.new("RGBA", (_CW * _SS, _CH * _SS), (0, 0, 0, 0))
    if lit:
        gl = Image.new("RGBA", im.size, (255, 200, 80, 0)); gl.putalpha(_mglow())
        im.alpha_composite(gl)
    d = ImageDraw.Draw(im)
    la, ra, lh, rh = POSES[pose](t)
    # legs + shoes (behind body)
    step = 6 * math.sin(t * 8) if pose in ("cheer",) else 0
    for lx, s in ((185, 1), (235, -1)):
        d.line([_P(lx, 470), _P(lx + 4 * s, 525 + step * s)], fill=_LIMB, width=14 * _SS)
        fx = lx + 4 * s
        d.ellipse(_R(fx - 30 + 10 * (-s), 515 + step * s, fx + 30 + 10 * (-s), 548 + step * s), fill=_BOOT, outline=_LINE, width=5 * _SS)
    # left arm (viewer's left) behind
    _arm(d, 82, 262, la[0], la[1], lh)
    # neck + screw base
    glass = _GLASS_ON if lit else _GLASS_OFF
    d.polygon([_P(128, 322), _P(292, 322), _P(262, 388), _P(158, 388)], fill=glass, outline=_LINE, width=7 * _SS)
    d.rounded_rectangle(_R(156, 384, 264, 458), 12 * _SS, fill=_GREY1, outline=_LINE, width=7 * _SS)
    for yy in (406, 428):
        d.line([_P(160, yy), _P(260, yy)], fill=_GREY2, width=7 * _SS)
    d.rounded_rectangle(_R(184, 454, 236, 478), 10 * _SS, fill=_LINE)
    # glass bulb
    d.ellipse(_R(60, 62, 360, 362), fill=glass, outline=_LINE, width=8 * _SS)
    d.arc(_R(92, 96, 300, 310), 200, 250, fill=(255, 250, 225), width=14 * _SS)   # shine
    # cheeks
    d.ellipse(_R(108, 246, 146, 270), fill=(255, 160, 110))
    d.ellipse(_R(274, 246, 312, 270), fill=(255, 160, 110))
    # eyes (blink)
    bl = 1.0
    ph = (t + extra) % 3.1
    if ph < 0.14: bl = max(0.08, abs(ph - 0.07) / 0.07)
    for ex in (164, 256):
        ew, eh = 30, 38 * bl
        d.ellipse(_R(ex - ew, 210 - eh, ex + ew, 210 + eh), fill="white", outline=_LINE, width=6 * _SS)
        if bl > 0.3:
            px, py = ex + 8 * look[0], 214 + 8 * look[1]
            pr = 15 if expr != "surprised" else 11
            d.ellipse(_R(px - pr, py - pr * bl, px + pr, py + pr * bl), fill=_LINE)
            d.ellipse(_R(px - 6, py - 9, px + 1, py - 2), fill="white")
    # brows
    if expr == "worried":
        d.line([_P(132, 156), _P(188, 168)], fill=_LINE, width=8 * _SS)
        d.line([_P(232, 168), _P(288, 156)], fill=_LINE, width=8 * _SS)
    elif expr in ("surprised", "grin"):
        d.arc(_R(136, 140, 192, 170), 200, 340, fill=_LINE, width=7 * _SS)
        d.arc(_R(228, 140, 284, 170), 200, 340, fill=_LINE, width=7 * _SS)
    # mouth
    mx, my = 210, 284
    if expr == "smile":
        d.arc(_R(mx - 42, my - 34, mx + 42, my + 20), 20, 160, fill=_LINE, width=8 * _SS)
    elif expr == "talk":
        h = 8 + 16 * abs(math.sin(t * 11))
        d.ellipse(_R(mx - 26, my - 6, mx + 26, my + h), fill=(120, 30, 30), outline=_LINE, width=6 * _SS)
    elif expr == "surprised":
        d.ellipse(_R(mx - 16, my - 10, mx + 16, my + 22), fill=(120, 30, 30), outline=_LINE, width=6 * _SS)
    elif expr == "worried":
        d.arc(_R(mx - 34, my, mx + 34, my + 40), 200, 340, fill=_LINE, width=8 * _SS)
    elif expr == "grin":
        d.chord(_R(mx - 46, my - 28, mx + 46, my + 34), 0, 180, fill=(120, 30, 30), outline=_LINE, width=7 * _SS)
        d.rectangle(_R(mx - 34, my + 2, mx + 34, my + 10), fill="white")
    # hard hat
    d.pieslice(_R(84, 26, 336, 196), 180, 360, fill=_HELM, outline=_LINE, width=7 * _SS)
    d.rectangle(_R(196, 30, 224, 110), fill=(255, 176, 70))
    d.rounded_rectangle(_R(62, 100, 358, 126), 13 * _SS, fill=_HELM, outline=_LINE, width=7 * _SS)
    # right arm (front)
    _arm(d, 338, 262, ra[0], ra[1], rh)
    # extras
    if expr == "worried":
        sy = 150 + 22 * ((t * 0.9) % 1)
        d.polygon([_P(352, sy - 26), _P(338, sy), _P(366, sy)], fill=(90, 170, 255))
        d.ellipse(_R(337, sy - 10, 367, sy + 18), fill=(90, 170, 255))
    if pose == "cheer" or expr == "grin":
        for i, (sx, sy, r) in enumerate([(40, 60, 26), (390, 40, 20), (420, 200, 16), (10, 210, 18)]):
            s = 0.6 + 0.4 * math.sin(t * 7 + i * 1.7)
            _star(d, sx, sy, r * s, (255, 220, 90))
    s = height / _CH
    return im.resize((max(1, int(_CW * s)), max(1, int(_CH * s))), Image.LANCZOS)

def place_mascot(img, cx, bottom, height, t, delay=0.0, **kw):
    p = back((t - delay) / 0.55)
    if p <= 0.02: return
    h = int(height * p)
    bob = int(-abs(math.sin(t * 3.2)) * height * 0.025)
    m = draw_mascot(h, t, **kw)
    img.paste(m, (int(cx - m.width / 2), int(bottom - m.height + bob)), m)


def bubble(img, ch, cx, cy, size, t, delay, tail_to):
    p = back((t - delay) / 0.45)
    if p <= 0.02: return
    s = size * p
    d = ImageDraw.Draw(img)
    tx, ty = tail_to
    sx = 1 if tx < cx else -1
    pu = beat_pulse(STYLE.get("_gt", 0.0))
    s *= 1 + 0.05 * pu
    tri = [(cx - sx * s * 0.18, cy + s * 0.25), (cx + sx * s * 0.05, cy + s * 0.38), (tx, ty)]
    box = [cx - s * 0.62, cy - s * 0.55, cx + s * 0.62, cy + s * 0.5]
    if LIGHT:
        ol = mix(BG1, FG, 0.18)
        d.polygon([(x + 0, y + 0) for x, y in tri], fill=ol)
        d.rounded_rectangle([box[0] - 4, box[1] - 4, box[2] + 4, box[3] + 4], int(s * 0.22) + 4, fill=ol)
    d.polygon(tri, fill=WHITE)
    d.rounded_rectangle(box, int(s * 0.22), fill=WHITE)
    bob = int(6 * math.sin(t * 2.5))
    e = emoji(ch, int(s * 0.7))
    img.paste(e, (int(cx - e.width / 2), int(cy - e.height / 2 - s * 0.03 + bob)), e)

def _mx(x, mirror):
    return W - x if mirror else x

# ---------- scenes ----------
def sc_hook(sp, t, gt, total):
    global RING_AT
    mr = STYLE.get("mirror", False)
    RING_AT = (_mx(W // 2 - 60, mr), 640, 300)
    img, d = base(t, gt, total)
    RING_AT = None
    pose = "wave" if t < 1.6 else "point"
    place_mascot(img, _mx(W // 2 - 60, mr), 890, 560, t, 0.05, pose=pose, lit=t > 0.12,
                 expr="surprised" if t < 0.9 else "talk", look=(0.4 if not mr else -0.4, -0.3))
    bubble(img, sp.get("emoji", "⚡"), _mx(820, mr), 400, 220, t, 0.5, (_mx(720, mr), 520))
    d = ImageDraw.Draw(img)
    kicker(d, sp.get("kicker", "WUSSTEN SIE?"), 920, t, 0.05)
    f = font("xb", 92)
    y = kinetic(img, wrap(d, sp["title"], f, 940), f, 1050, 108, t, 0.15, mode=STYLE.get("hook_mode", "slam"), stagger=0.09)
    d = ImageDraw.Draw(img)
    if sp.get("sub"):
        f2 = font("sb", 46)
        lines_anim(d, wrap(d, sp["sub"], f2, 900), f2, y + 40, 62, t, 0.7, GREY)
    return img

def sc_point(sp, t, gt, total):
    global RING_AT
    mr = STYLE.get("mirror", False) ^ (sp.get("_idx", 0) % 2 == 0)
    RING_AT = (_mx(775, mr), 520, 210)
    img, d = base(t, gt, total)
    RING_AT = None
    bad = sp.get("mood", "bad" if "PROBLEM" in sp.get("kicker", "") else "good") == "bad"
    lk = (0.6 if not mr else -0.6, -0.2)
    if bad:
        place_mascot(img, _mx(330, mr), 850, 480, t, 0.1, pose="worried", expr="worried", lit=False, look=lk)
    else:
        place_mascot(img, _mx(330, mr), 850, 480, t, 0.1, pose="thumb" if t > 0.6 else "idle", lit=t > 0.32,
                     expr=("surprised" if t < 0.6 else "talk" if (t % 2.2) < 1.4 else "smile"), look=lk)
    bubble(img, sp.get("emoji", "💡"), _mx(775, mr), 520, 280, t, 0.35, (_mx(590, mr), 650))
    d = ImageDraw.Draw(img)
    kicker(d, sp.get("kicker", ""), 880, t, 0.25)
    f = font("xb", 96)
    y = kinetic(img, wrap(d, sp["title"], f, 940), f, 1010, 112, t, 0.3)
    d = ImageDraw.Draw(img)
    a = ease((t - 0.7) / 0.5)
    d.rectangle([W / 2 - 200 * a, y + 20, W / 2 + 200 * a, y + 30], fill=OR)
    d.rectangle([W / 2 + 200 * a - 40 * a, y + 20, W / 2 + 200 * a, y + 30], fill=ACC2)
    if sp.get("body"):
        f2 = font("sb", 48)
        lines_anim(d, wrap(d, sp["body"], f2, 900), f2, y + 80, 66, t, 0.8, GREY, 0.08)
    return img

def sc_bullets(sp, t, gt, total):
    img, d = base(t, gt, total)
    place_mascot(img, 950, 400, 270, t, 0.2, pose="thumb", expr="smile" if (t % 2.0) > 1.2 else "talk", look=(-0.6, 0.5))
    d = ImageDraw.Draw(img)
    kicker(d, sp.get("kicker", "UNSER TIPP"), 430, t, 0.25)
    f = font("xb", 84)
    y = kinetic(img, wrap(d, sp["title"], f, 940), f, 550, 100, t, 0.3)
    d = ImageDraw.Draw(img)
    fi = font("b", 54)
    y += 70
    for i, it in enumerate(sp["items"]):
        a = ease((t - 0.8 - i * 0.28) / 0.45)
        if a <= 0: continue
        x0 = 90 + int((1 - back((t - 0.8 - i * 0.28) / 0.45)) * (-700 if i % 2 == 0 else 700))
        d.rounded_rectangle([x0, y, x0 + 900, y + 130], 26, fill=mix(BG2, PANEL, a))
        d.rounded_rectangle([x0, y, x0 + 14, y + 130], 7, fill=mix(BG2, OR if i % 2 == 0 else ACC2, a))
        ic = sp.get("item_emoji", STYLE.get("item_emoji", "✅"))
        e = emoji(ic, 64); img.paste(e, (x0 + 50, y + 33), e)
        lines = wrap(d, it, fi, 700)[:2]
        if len(lines) == 1:
            d.text((x0 + 150, y + 32), lines[0], font=fi, fill=mix(BG2, FG, a))
        else:
            f3 = font("b", 42)
            lines = wrap(d, it, f3, 700)[:2]
            for k, ln in enumerate(lines):
                d.text((x0 + 150, y + 18 + k * 50), ln, font=f3, fill=mix(BG2, FG, a))
        y += 160
    return img

def _on_acc():
    return WHITE if LIGHT else (22, 16, 10)

def sc_calc(sp, t, gt, total):
    img, d = base(t, gt, total)
    _rv = 0.8 + len(sp["rows"]) * 1.0 + 0.4
    if t > _rv:
        q = min(1.0, (t - _rv) / 0.5)
        cxr, cyr = W / 2, 1545
        for k in range(14):
            ang = math.radians(k * 360 / 14 + (t - _rv) * 25); ang2 = ang + math.radians(9); rr = 760 * q
            d.polygon([(cxr, cyr), (cxr + rr * math.cos(ang), cyr + rr * math.sin(ang)), (cxr + rr * math.cos(ang2), cyr + rr * math.sin(ang2))],
                      fill=mix(BG2, OR, 0.14))
    if t < _rv + 0.9:
        place_mascot(img, 950, 390, 260, t, 0.2, pose="pointdown", expr="talk", look=(-0.5, 0.6))
    else:
        place_mascot(img, 950, 390, 260, t, 0.0, pose="cheer", expr="grin", look=(-0.3, 0.4))
    d = ImageDraw.Draw(img)
    kicker(d, sp.get("kicker", "DIE RECHNUNG"), 360, t, 0.2)
    f = font("xb", 70)
    y = kinetic(img, wrap(d, sp["title"], f, 960), f, 460, 84, t, 0.25)
    d = ImageDraw.Draw(img)
    rows = sp["rows"]
    mx = max(r["eur"] for r in rows)
    y += 60
    cols = [mix(GREY, BG2, 0.15), OR, (70, 190, 110)]
    for i, r in enumerate(rows):
        t0 = 0.8 + i * 1.0
        p, al = ease((t - t0) / 0.9), ease((t - t0) / 0.3)
        col = tuple(r["color"]) if "color" in r else cols[min(i, 2)]
        d.text((80, y), r["label"], font=font("xb", 40), fill=mix(BG2, col, al))
        d.text((80, y + 52), r["desc"], font=font("sb", 36), fill=mix(BG2, GREY, al))
        d.rounded_rectangle([80, y + 112, 1000, y + 182], 16, fill=mix(BG2, PANEL, al))
        bw = int(920 * r["eur"] / mx * p)
        if bw > 24: d.rounded_rectangle([80, y + 112, 80 + bw, y + 182], 16, fill=col)
        if r.get("value"): d.text((80, y + 200), r["value"], font=font("sb", 38), fill=mix(BG2, GREY, al))
        et = f"{de(r['eur'] * p)} €"
        ew = d.textlength(et, font=font("xb", 62))
        d.text((1000 - ew, y + 186), et, font=font("xb", 62), fill=mix(BG2, FG, al))
        y += 320
    reveal = 0.8 + len(rows) * 1.0 + 0.4
    p, al = ease((t - reveal) / 1.0), ease((t - reveal) / 0.3)
    if al > 0:
        by = max(y + 10, 1400)
        d.rounded_rectangle([80, by, 1000, by + 290], 32, fill=mix(BG2, OR, al))
        def ct(yy, s, f, c):
            w = d.textlength(s, font=f); d.text(((W - w) / 2, yy), s, font=f, fill=c)
        ct(by + 26, sp.get("save_label", "SIE SPAREN CA."), font("xb", 44), mix(OR, _on_acc(), al))
        pop = 1 + 0.09 * max(0, 1 - abs(t - (reveal + 1.0)) / 0.15)
        ct(by + 80, f"{de(sp['save'] * p)} €", font("xb", int(132 * pop)), mix(OR, WHITE, al))
        ct(by + 228, sp.get("save_sub", "pro Jahr"), font("sb", 38), mix(OR, _on_acc(), al))
        burst(d, W / 2, by + 145, t, reveal + 0.95, n=18, R=420, col=ACC2)
        confetti(d, W / 2, by + 60, t, reveal + 0.95)
        a = ease((t - reveal - 0.8) / 0.5)
        if sp.get("foot"):
            ff = font("sb", 28)
            for k, ln in enumerate(wrap(d, sp["foot"], ff, 940)):
                ct(by + 320 + k * 38, ln, ff, mix(BG2, DGREY, a))
    return img

def sc_stat(sp, t, gt, total):
    """Big fact/number scene for topics without a savings calculation."""
    img, d = base(t, gt, total)
    kicker(d, sp.get("kicker", "WUSSTEN SIE?"), 290, t, 0.15)
    p = ease((t - 0.4) / 1.2)
    v = sp.get("value", 0)
    dec = sp.get("decimals", 0)
    num = de(v * p, dec) if isinstance(v, (int, float)) else str(v)
    txt = f"{sp.get('prefix', '')}{num}{sp.get('suffix', '')}"
    pop = 1 + 0.08 * max(0, 1 - abs(t - 1.6) / 0.15)
    f = font("xb", int(sp.get("size", 180) * pop))
    a = ease((t - 0.3) / 0.3)
    cx0, cy0, rr = W / 2, 740, 345
    d.ellipse([cx0 - rr, cy0 - rr, cx0 + rr, cy0 + rr], outline=mix(BG2, PANEL2, a), width=22)
    frac = (v / 100.0) if ("%" in sp.get("suffix", "") and isinstance(v, (int, float))) else 1.0
    if p > 0.01:
        d.arc([cx0 - rr, cy0 - rr, cx0 + rr, cy0 + rr], -90, -90 + 360 * frac * p, fill=OR, width=22)
        ang = math.radians(-90 + 360 * frac * p)
        d.ellipse([cx0 + rr * math.cos(ang) - 20, cy0 + rr * math.sin(ang) - 20, cx0 + rr * math.cos(ang) + 20, cy0 + rr * math.sin(ang) + 20], fill=ACC2)
    burst(d, cx0, cy0, t, 1.55, n=16, R=420, col=ACC2)
    tw = d.textlength(txt, font=f)
    d.text(((W - tw) / 2, cy0 - f.size * 0.62), txt, font=f, fill=mix(BG2, FG, a))
    fl = font("b", 60)
    y = lines_anim(d, wrap(d, sp["label"], fl, 900), fl, 1150, 76, t, 1.0)
    if sp.get("source"):
        a2 = ease((t - 1.6) / 0.5)
        fs = font("sb", 30)
        for k, ln in enumerate(wrap(d, sp["source"], fs, 900)):
            w = d.textlength(ln, font=fs); d.text(((W - w) / 2, y + 40 + k * 40), ln, font=fs, fill=mix(BG2, DGREY, a2))
    place_mascot(img, W // 2, 1895, 350, t, 0.6, pose="point" if t < 2.5 else "thumb",
                 expr="surprised" if t < 1.8 else "talk", look=(0.0, -0.8))
    return img

SLOGAN1, SLOGAN2 = "VERBINDUNG, DIE HÄLT.", "QUALITÄT, DIE BLEIBT."
def sc_outro(sp, t, gt, total):
    img = Image.new("RGB", (W, H), WHITE)
    d = ImageDraw.Draw(img)
    g = ease(t / 0.8); L = int(380 * g); m = 70
    for (x, y, dx, dy) in [(m, m, 1, 1), (W - m, H - m - 14, -1, -1)]:
        d.line([(x, y), (x + dx * L, y)], fill=BRAND, width=8); d.line([(x, y), (x, y + dy * L)], fill=BRAND, width=8)
    p = ease(t / 0.7); s = 0.82 + 0.18 * p
    lg = logo(int(820 * s))
    if p < 1: lg = lg.filter(ImageFilter.GaussianBlur((1 - p) * 8))
    cy = H // 2 - 170
    img.paste(lg, ((W - lg.width) // 2, cy - lg.height // 2), Image.new("L", lg.size, int(255 * min(1, p * 1.4))))
    d = ImageDraw.Draw(img)
    q = (t - 0.45) / 0.7
    if 0 < q < 1:
        e = ease(q)
        for i in range(20):
            a_ = 2 * math.pi * i / 20; r1, r2 = 520 * 0.3 + 520 * e, 520 * 0.3 + 520 * e + 60 * (1 - q)
            d.line([(W / 2 + r1 * math.cos(a_), cy + r1 * math.sin(a_)), (W / 2 + r2 * math.cos(a_), cy + r2 * math.sin(a_))],
                   fill=mix(WHITE, BRAND, 1 - q), width=max(1, int(10 * (1 - q))))
    b = ease((t - 0.4) / 0.6); bw = int(520 * b); by = cy + 110
    d.rectangle([(W - bw) // 2, by, (W + bw) // 2, by + 10], fill=BRAND)
    def ct(yy, s_, f, c):
        w = d.textlength(s_, font=f); d.text(((W - w) / 2, yy), s_, font=f, fill=c)
    a = ease((t - 0.7) / 0.6); ct(by + 60 + (1 - a) * 30, SLOGAN1, font("xb", 58), mix(WHITE, (20, 20, 20), a))
    a = ease((t - 1.0) / 0.6); ct(by + 140 + (1 - a) * 30, SLOGAN2, font("xb", 58), mix(WHITE, BRAND, a))
    a = ease((t - 1.4) / 0.6); ct(by + 260, "Ihr Fachpartner für Elektrotechnik", font("sb", 44), mix(WHITE, (110, 110, 110), a))
    a3 = ease((t - 1.8) / 0.5)
    if a3 > 0:
        cta = sp.get("cta", "JETZT BERATUNG ANFRAGEN"); f3 = font("xb", 46)
        cw = d.textlength(cta, font=f3); s3 = 0.9 + 0.1 * a3
        bw2, bh2 = (cw + 100) * s3, 110 * s3; c3 = by + 420
        d.rounded_rectangle([(W - bw2) / 2, c3 - bh2 / 2, (W + bw2) / 2, c3 + bh2 / 2], int(55 * s3), fill=mix(WHITE, BRAND, a3))
        d.text(((W - cw) / 2, c3 - 30), cta, font=f3, fill=WHITE)
    a4 = ease((t - 2.2) / 0.5)
    if a4 > 0:
        ct(by + 520 + (1 - a4) * 20, "www.dk-e-technik.de", font("xb", 50), mix(WHITE, (20, 20, 20), a4))
    place_mascot(img, 250, 1835, 330, t, 0.9, pose="wave", expr="talk" if t < 2.6 else "smile", look=(0.5, -0.4))
    return img

SCENES = {"hook": sc_hook, "point": sc_point, "bullets": sc_bullets, "calc": sc_calc, "stat": sc_stat, "outro": sc_outro}

# ---------- music: procedural, genre/key/tempo/progression vary per episode ----------
def music(path, dur, cuts, drop, brk, end, st):
    from scipy.signal import butter, sosfilt, fftconvolve
    SR = 44100
    genre = st["genre"]; bpm = st["bpm"]
    B = 60.0 / bpm; BAR = 4 * B; S16 = B / 4
    N = int(SR * dur) + SR
    L = np.zeros(N); R = np.zeros(N); VL = np.zeros(N); VR = np.zeros(N)
    rng = np.random.default_rng(st["seed"] * 104729 + 3)
    mtof = lambda m: 440.0 * 2 ** ((m - 69) / 12)
    def lp(x, fc, o=2): return sosfilt(butter(o, min(fc, SR / 2 - 200) / (SR / 2), output="sos"), x)
    def hp(x, fc, o=2): return sosfilt(butter(o, fc / (SR / 2), btype="high", output="sos"), x)
    def bp(x, lo, hi): return sosfilt(butter(2, [lo / (SR / 2), hi / (SR / 2)], btype="band", output="sos"), x)
    def add(sig, t, g=1.0, pan=0.0, verb=0.0):
        i = int(round(t * SR))
        if i >= N or len(sig) == 0: return
        if i < 0: sig = sig[-i:]; i = 0
        j = min(N, i + len(sig)); s = sig[: j - i] * g
        gl, gr = math.cos((pan + 1) * math.pi / 4) * 1.414, math.sin((pan + 1) * math.pi / 4) * 1.414
        L[i:j] += s * gl; R[i:j] += s * gr
        if verb: VL[i:j] += s * gl * verb; VR[i:j] += s * gr * verb
    inb = lambda t: brk[0] <= t < brk[1]
    full = lambda t: drop <= t < end and not inb(t)
    def tarr(sec): return np.arange(int(sec * SR)) / SR
    def saw(f, t): return 2 * ((f * t) % 1) - 1
    def env(t, a=0.003, dcy=6.0): return np.minimum(1, t / a) * np.exp(-t * dcy)

    # harmony
    root = st["key"]; minor = st["minor"]
    scale = [0, 2, 3, 5, 7, 8, 10] if minor else [0, 2, 4, 5, 7, 9, 11]
    def deg(dg, octv=0):
        return root + scale[dg % 7] + 12 * (dg // 7) + 12 * octv
    def chord(dg, octv=1, n=4):
        return [deg(dg + 2 * k, octv) for k in range(n)]
    prog = st["prog"]
    def bar_of(t): return int(math.floor((t - drop) / BAR + 1e-6))
    def chord_at(t): return prog[bar_of(t) % 4]

    # ---------- instruments ----------
    def tone(kind, f, ln):
        t = tarr(ln)
        if kind == "pluck":
            return lp(saw(f, t) + 0.5 * saw(f * 1.005, t), 2600) * env(t, 0.002, 9)
        if kind == "bell":
            return np.sin(2 * np.pi * f * t + 2.2 * np.exp(-t * 6) * np.sin(2 * np.pi * 3.5 * f * t)) * env(t, 0.002, 4)
        if kind == "marimba":
            return (np.sin(2 * np.pi * f * t) * env(t, 0.002, 8) + 0.35 * np.sin(2 * np.pi * 4 * f * t) * env(t, 0.001, 35))
        if kind == "piano":
            return sum(np.sin(2 * np.pi * h * f * t + h) / h ** 1.4 * np.exp(-t * (2.2 + 1.3 * h)) for h in range(1, 7)) * np.minimum(1, t / 0.004)
        if kind == "rhodes":
            return (np.sin(2 * np.pi * f * t) + 0.35 * np.sin(2 * np.pi * 2 * f * t) * np.exp(-t * 4)) * np.exp(-t * 1.3) * (1 + 0.18 * np.sin(2 * np.pi * 5 * t)) * np.minimum(1, t / 0.01)
        if kind == "supersaw":
            s = sum(saw(f * (1 + dt), t + rng.random()) for dt in (-0.012, -0.007, -0.003, 0, 0.003, 0.007, 0.012)) / 4
            return lp(s, 4200) * np.minimum(1, t / 0.01) * np.minimum(1, (ln - t) / 0.05)
        if kind == "pad":
            s = sum(saw(f * (1 + dt), t + rng.random()) for dt in (-0.006, 0, 0.006)) / 3
            return lp(s, 1400) * np.minimum(1, t / 0.25) * np.minimum(1, (ln - t) / 0.25)
        if kind == "lead":
            vib = 1 + 0.004 * np.sin(2 * np.pi * 5.5 * t) * np.minimum(1, t / 0.2)
            return lp(saw(f * vib, t) + 0.6 * np.sign(np.sin(2 * np.pi * f * 0.5 * t)) * 0.4, 3200) * np.minimum(1, t / 0.01) * np.exp(-t * 2.5)
        return np.sin(2 * np.pi * f * t) * env(t, 0.005, 3)

    # drums
    tk = tarr(0.5)
    kick_f = {"hiphop": (48, 140, 30), "dnb": (52, 200, 45), "futurebass": (46, 180, 38)}.get(genre, (45, 190, 42))
    KICK = np.sin(2 * np.pi * np.cumsum(kick_f[0] + kick_f[1] * np.exp(-tk * kick_f[2])) / SR) * np.exp(-tk * (4.0 if genre == "hiphop" else 5.2))
    KICK[:90] += np.linspace(1, 0, 90) * 0.6
    KICK = np.tanh(2.6 * KICK) * 0.9
    th = tarr(0.045); HAT = hp(rng.standard_normal(len(th)), 8500) * np.exp(-th * 95) * 0.3
    to = tarr(0.22); OHAT = hp(bp(rng.standard_normal(len(to)), 6000, 15000), 7000) * np.exp(-to * 14) * 0.32
    tcl = tarr(0.35); e = np.zeros(len(tcl))
    for dd in (0, 0.008, 0.017, 0.026):
        k = int(dd * SR); e[k:] += np.exp(-np.arange(len(tcl) - k) / SR * (70 if dd < 0.026 else 12))
    CLAP = bp(rng.standard_normal(len(tcl)), 1000, 7000) * e * 0.42
    ts = tarr(0.3)
    SNARE = (bp(rng.standard_normal(len(ts)), 1500, 9000) * np.exp(-ts * 16) * 0.5 +
             np.sin(2 * np.pi * 190 * ts) * np.exp(-ts * 25) * 0.5)
    tsh = tarr(0.07); SHAKER = bp(rng.standard_normal(len(tsh)), 5000, 12000) * np.minimum(1, tsh / 0.015) * np.exp(-tsh * 50) * 0.22
    tpc = tarr(0.12); PERC = np.sin(2 * np.pi * np.cumsum(520 + 300 * np.exp(-tpc * 40)) / SR) * np.exp(-tpc * 30) * 0.22
    tcr = tarr(2.4); CRASH = hp(rng.standard_normal(len(tcr)), 5000) * np.exp(-tcr * 1.8) * 0.24

    swing = S16 * (0.18 if genre == "hiphop" else 0.08 if genre == "afro" else 0.0)
    kmin = -int(math.ceil(drop / B)) - 1
    kmax = int((dur - drop) / B) + 2
    kick_times = []
    pats = {   # 16th steps per bar: kick, snare/clap, hats
        "house":      ([0, 4, 8, 12], [4, 12], "off8+16"),
        "techno":     ([0, 4, 8, 12], [4, 12], "16"),
        "hiphop":     ([0, 7, 10], [4, 12], "8"),
        "futurebass": ([0, 10], [8], "8"),
        "synthwave":  ([0, 4, 8, 12], [4, 12], "8"),
        "afro":       ([0, 4, 8, 12], [12], "shaker"),
        "dnb":        ([0, 10], [4, 12], "8"),
    }
    kp, sn, hp_ = pats[genre]
    for bi in range((kmin // 4) - 1, kmax // 4 + 2):
        for q in range(16):
            t = drop + bi * BAR + q * S16 + (swing if q % 2 else 0)
            if t < 0 or t >= dur: continue
            if full(t):
                if q in kp:
                    add(KICK, t, 1.0); kick_times.append(t)
                if q in sn:
                    if genre in ("house", "techno", "afro"): add(CLAP, t, 0.8, 0.0, 0.35)
                    else: add(SNARE, t, 0.85 if genre != "synthwave" else 0.7, 0.0, 0.6 if genre in ("synthwave", "futurebass") else 0.3)
                if hp_ == "16" or (hp_ == "off8+16" and q % 2 == 0) or (hp_ == "8" and q % 2 == 0):
                    acc = 1.0 if q % 4 == 0 else 0.55
                    add(HAT, t, acc * (0.8 if hp_ != "16" else 1.0), -0.25 + 0.03 * q)
                if hp_ == "off8+16" and q % 4 == 2: add(OHAT, t, 0.9, 0.2)
                if genre == "techno" and q % 4 == 2: add(OHAT, t, 0.8, 0.2)
                if hp_ == "shaker": add(SHAKER, t, 1.0 if q % 4 == 2 else 0.5, 0.3)
                if genre == "afro" and q in (3, 6, 11, 14): add(PERC, t, 0.9, -0.4 if q < 8 else 0.4, 0.3)
                if genre == "dnb" and q in (6, 14): add(SNARE, t, 0.25, 0.2, 0.2)
                if genre == "hiphop" and q == 15 and bi % 2: add(HAT, t, 0.6, 0.3)
            else:
                if (drop - 2 * BAR <= t < drop or inb(t)) and q % 4 == 2:
                    add(HAT, t, 0.5, 0.25)
                if inb(t) and q == 0: add(lp(KICK, 300), t, 0.45)
    def build(t_end, length):
        steps = int(length / S16)
        for q in range(steps):
            g = 0.1 + 0.6 * (q / steps) ** 1.5
            add(SNARE if genre not in ("house", "techno", "afro") else CLAP, t_end - length + q * S16, g * 0.8, 0, 0.25)
    if drop >= 1.0: build(drop, min(2 * B * 2, drop))
    if brk[1] - brk[0] > 1.2: build(brk[1], min(4 * B, brk[1] - brk[0]))
    for tc in (drop, brk[1], end):
        if 0 < tc < dur: add(CRASH, tc, 1.0, 0.0, 0.3)

    tt_all = np.arange(N) / SR
    sc = np.ones(N)
    depth = 0.92 if genre in ("futurebass", "house") else 0.8
    for kt in kick_times:
        i = int(kt * SR); j = min(N, i + int(0.45 * SR))
        sc[i:j] = np.minimum(sc[i:j], 1 - depth * np.exp(-(tt_all[i:j] - kt) / 0.12))

    # ---------- bass ----------
    bass = np.zeros(N)
    nb = int(dur / BAR) + 2
    for bi in range(-2, nb):
        t_bar = drop + bi * BAR
        rt = deg(chord_at(t_bar + 0.01), -1) if True else 0
        if genre == "techno":
            steps = [(q, [0, 0, 12, 0, 0, 0, 12, 0, 0, 0, 12, 0, 0, 7, 12, 0][q], S16 * 0.9) for q in range(16) if q % 4]
            kind = "saw"
        elif genre == "house":
            steps = [(q, 0 if q != 14 else 12, S16 * 1.6) for q in (2, 6, 10, 14)]; kind = "saw"
        elif genre == "synthwave":
            steps = [(q, 0 if (q // 2) % 2 == 0 else 12, S16 * 1.8) for q in range(0, 16, 2)]; kind = "saw"
        elif genre == "afro":
            steps = [(q, [0, 0, 7, 0, 12][k], S16 * 2.2) for k, q in enumerate((0, 3, 6, 10, 12))]; kind = "sub"
        elif genre == "hiphop":
            steps = [(0, 0, B * 1.6), (7, 0, B * 0.7), (10, 7 if rng.random() < 0.5 else 0, B * 1.4)]; kind = "sub"
        elif genre == "futurebass":
            steps = [(0, 0, B * 2.4), (10, 0, B * 1.4)]; kind = "sub"
        else:  # dnb
            steps = [(0, 0, BAR * 0.95)]; kind = "reese"
        for q, off, ln in steps:
            t0 = t_bar + q * S16 + (swing if q % 2 else 0)
            if t0 < 0 or not full(t0): continue
            f = mtof(rt + 12 + off) if kind != "sub" else mtof(rt + off)
            t = tarr(ln)
            if kind == "saw": s = saw(f, t) * np.minimum(1, t / 0.003) * np.exp(-t * (9 if genre == "techno" else 4))
            elif kind == "sub": s = np.tanh(1.6 * np.sin(2 * np.pi * f * t)) * np.minimum(1, t / 0.01) * np.minimum(1, (ln - t) / 0.03)
            else: s = (saw(f, t) + saw(f * 1.01, t + 0.3)) * 0.5 * np.minimum(1, t / 0.02) * np.minimum(1, (ln - t) / 0.05)
            i = int(t0 * SR); j = min(N, i + len(s)); bass[i:j] += s[: j - i]
    if genre in ("techno", "dnb", "house"):
        bf = np.zeros(N); zi = None
        for s0 in range(0, N, 512):
            fc = (380 if genre != "dnb" else 260) + 900 * (0.5 + 0.5 * math.sin(2 * math.pi * (s0 / SR) / (8 * BAR)))
            sos = butter(2, fc / (SR / 2), output="sos")
            if zi is None: zi = np.zeros((sos.shape[0], 2))
            bf[s0:s0 + 512], zi = sosfilt(sos, bass[s0:s0 + 512], zi=zi)
        bass = bf
    else:
        bass = lp(bass, 700)
    add(np.tanh(bass * 2.0) * sc * 0.42, 0, 1.0)

    # ---------- chords ----------
    ch_kind = {"house": "piano", "techno": "pluck", "hiphop": "rhodes", "futurebass": "supersaw",
               "synthwave": "pad", "afro": "pad", "dnb": "pad"}[genre]
    chords = np.zeros(N)
    for bi in range(-1, nb):
        t_bar = drop + bi * BAR
        if t_bar + BAR < drop - BAR or t_bar >= end: continue
        notes = chord(chord_at(t_bar + 0.01), 1)
        if ch_kind in ("piano", "pluck"):
            hits = [(3, 0.25), (6, 0.25), (10, 0.3)] if ch_kind == "piano" else [(3, 0.22), (10, 0.22)]
        else:
            hits = [(0, BAR * 0.98)]
        for q, ln in hits:
            t0 = t_bar + q * S16
            if t0 < max(0, drop - BAR) or t0 >= end: continue
            s = sum(tone(ch_kind, mtof(m), ln + (0.25 if ch_kind in ("piano", "pluck") else 0)) for m in notes) / len(notes)
            g = (0.5 if t0 < drop else 1.0) * (0.6 if inb(t0) else 1.0)
            i = int(t0 * SR); j = min(N, i + len(s)); chords[i:j] += s[: j - i] * g
    cg = {"piano": 0.22, "pluck": 0.2, "rhodes": 0.22, "supersaw": 0.20, "pad": 0.16}[ch_kind]
    chords = chords * (sc if genre in ("futurebass", "house", "techno", "synthwave") else (0.7 + 0.3 * sc))
    add(chords * cg, 0, 1.0, 0.0, 0.45)
    if ch_kind in ("pluck", "piano"):
        dl = int(3 * S16 * SR); fb = chords.copy(); echo = np.zeros(N)
        for k in range(1, 4):
            fb = np.concatenate([np.zeros(dl), fb[:-dl]]) * 0.4; echo += lp(fb, 1800 - 300 * k)
        add(echo * cg, 0, 0.8, 0.5, 0.3); add(np.roll(echo, dl // 2) * cg, 0, 0.6, -0.5, 0.3)

    # ---------- lead / melody motif (fresh per seed) ----------
    lead_kind = {"house": "pluck", "techno": None, "hiphop": "bell", "futurebass": "pluck",
                 "synthwave": "lead", "afro": "marimba", "dnb": "bell"}[genre]
    if genre == "synthwave":
        # classic 16th arpeggio over chord tones
        arp = np.zeros(N)
        for bi in range(0, nb):
            t_bar = drop + bi * BAR
            notes = chord(chord_at(t_bar + 0.01), 2, 3)
            for q in range(16):
                t0 = t_bar + q * S16
                if not full(t0): continue
                m = notes[[0, 1, 2, 1][q % 4]] + (12 if q % 8 >= 4 else 0)
                s = tone("pluck", mtof(m), S16 * 1.5)
                i = int(t0 * SR); j = min(N, i + len(s)); arp[i:j] += s[: j - i]
        add(arp * 0.10, 0, 1.0, 0.25, 0.35)
    if lead_kind:
        mot = []
        stepq = 2 if genre in ("hiphop", "dnb") else 1
        dens = 0.55
        pos = [q for q in range(0, 32, 2 * stepq) if rng.random() < dens] or [0, 6, 12]
        for q in pos:
            mot.append((q, int(rng.choice([0, 2, 4, 4, 7, 5, 9, 7]))))
        lead = np.zeros(N)
        for rep in range(0, nb, 2):
            t2 = drop + rep * BAR
            for q, dg in mot:
                t0 = t2 + q * S16 + (swing if q % 2 else 0)
                if not full(t0) or t0 < drop + (0 if genre != "afro" else 0): continue
                b = chord_at(t0)
                m = deg(b + dg, 2 if lead_kind != "lead" else 1)
                if lead_kind == "lead" and rep % 4 == 2: m += 0
                s = tone(lead_kind, mtof(m), 0.6 if lead_kind != "lead" else B * 1.2)
                i = int(t0 * SR); j = min(N, i + len(s)); lead[i:j] += s[: j - i]
        lg = {"pluck": 0.13, "bell": 0.12, "marimba": 0.16, "lead": 0.10}[lead_kind]
        add(lead * lg, 0, 1.0, -0.2, 0.4)
        dl = int(3 * S16 * SR); add(np.concatenate([np.zeros(dl), lead[:-dl]]) * lg * 0.35, 0, 1.0, 0.45, 0.4)

    # ---------- atmosphere pad under everything ----------
    pad = np.zeros(N)
    for bi in range(-int(drop / BAR) - 2, nb + 1):
        t0 = drop + bi * BAR; i0 = max(0, int(t0 * SR)); i1 = min(N, int((t0 + BAR + 0.1) * SR))
        if i1 <= i0: continue
        t = np.arange(i1 - i0) / SR
        v = sum(np.sin(2 * np.pi * mtof(m) * (1 + det) * t + rng.random() * 6) for m in chord(chord_at(t0 + 0.01), 1) for det in (-0.003, 0.003))
        pad[i0:i1] += v * np.minimum(1, t / 0.3) * np.minimum(1, (len(t) / SR - t) / 0.3) * 0.02
    add(lp(pad, 1500) * (0.6 + 0.4 * sc), 0, 1.0, 0.0, 0.5)

    # ---------- fx ----------
    def riser(ln):
        t = tarr(ln); n = rng.standard_normal(len(t)); o = np.zeros_like(n)
        for s0 in range(0, len(n), 1024):
            fr = s0 / len(n)
            o[s0:s0 + 1024] = bp(n[s0:s0 + 1024], 300 + 5000 * fr ** 2, 900 + 9000 * fr ** 2)
        return o * (t / ln) ** 2.2 * 0.3
    def sweep_down(ln=1.0):
        t = tarr(ln)
        return lp(rng.standard_normal(len(t)), 2000) * np.exp(-t * 3.5) * 0.22
    if drop > 0.5: add(riser(min(2.0, drop)), drop - min(2.0, drop), 1.0, 0, 0.2)
    add(riser(max(0.5, brk[1] - brk[0])), brk[0], 0.75, 0, 0.2)
    for c in cuts:
        if abs(c - drop) > 0.1 and abs(c - end) > 0.1 and abs(c - brk[0]) > 0.1:
            add(sweep_down(0.7), c, 0.5, 0, 0.1)
    add(KICK, end, 1.1)
    t = tarr(max(0.5, dur - end))
    fin = sum(np.sin(2 * np.pi * mtof(m) * t) for m in [deg(0, -1)] + chord(0, 1) + [deg(7, 1)])
    add(lp(fin, 1800) * np.exp(-t * 0.9) * 0.05, end, 1.0, 0, 0.6)
    if lead_kind:
        add(tone(lead_kind, mtof(deg(7, 1)), 1.5) * 0.12, end + 0.05, 1.0, 0.2, 0.6)

    # ---------- reverb + master ----------
    tr = tarr(1.8 if genre in ("synthwave", "futurebass") else 1.4)
    dec_ = 0.45 if genre in ("synthwave", "futurebass") else 0.35
    irL = lp(rng.standard_normal(len(tr)), 5500) * np.exp(-tr / dec_)
    irR = lp(rng.standard_normal(len(tr)), 5500) * np.exp(-tr / dec_)
    irL /= np.sqrt(np.sum(irL ** 2)); irR /= np.sqrt(np.sum(irR ** 2))
    L += fftconvolve(VL, irL)[:N] * 0.45
    R += fftconvolve(VR, irR)[:N] * 0.45
    stx = np.stack([L, R], 1)[: int(SR * dur)]
    stx = hp(stx.T, 30).T
    stx = stx / (np.max(np.abs(stx)) + 1e-9)
    stx = np.tanh(stx * 2.0) / np.tanh(2.0)
    fo = int(1.2 * SR); stx[-fo:] *= np.linspace(1, 0, fo)[:, None]
    stx = stx / np.max(np.abs(stx)) * 0.89
    with wave.open(path, "w") as w:
        w.setnchannels(2); w.setsampwidth(2); w.setframerate(SR)
        w.writeframes((stx * 32767).astype(np.int16).tobytes())

# ---------- render ----------
def post(fr, sp, t, gt, total):
    """Camera move per scene + beat punch + rotation, then progress bar."""
    dur = sp["dur"]; u = ease(t / max(0.1, dur)); idx = sp.get("_idx", 0)
    if sp["type"] == "outro":
        return progress(fr, gt, total)
    mv = STYLE["moves"][idx % len(STYLE["moves"])]
    z = 1.015; dx = dy = 0.0; rot = 0.0
    if mv == "push": z += 0.035 * u
    elif mv == "pull": z += 0.035 * (1 - u)
    elif mv == "drift": dx = (u - 0.5) * 30 * (1 if idx % 2 else -1); z += 0.02
    elif mv == "tilt": rot = (u - 0.5) * 1.6 * (1 if idx % 2 else -1); z += 0.025
    z += STYLE["punch"] * beat_pulse(gt)
    if gt >= STYLE["drop"] and gt - STYLE["drop"] < 0.25:
        sh = (1 - (gt - STYLE["drop"]) / 0.25) * 10
        dx += sh * math.sin(gt * 90); dy += sh * math.cos(gt * 77)
    if abs(rot) > 0.01:
        fr = fr.rotate(rot, resample=Image.BILINEAR, fillcolor=BG1)
    fr = camera(fr, z, dx, dy)
    return progress(fr, gt, total)

def render_scene(fn, sp, t0, total, path):
    dur = sp["dur"]; n = int(round(dur * FPS))
    tmp = path + ".part.mp4"
    p = subprocess.Popen(["ffmpeg", "-v", "error", "-y", "-f", "rawvideo", "-pix_fmt", "rgb24", "-s", f"{W}x{H}",
                          "-r", str(FPS), "-i", "-", "-c:v", "libx264", "-preset", "veryfast", "-crf", "18",
                          "-pix_fmt", "yuv420p", tmp], stdin=subprocess.PIPE)
    idx, last = sp.get("_idx", 0), sp.get("_last", False)
    tr_in = STYLE["trans"][(idx - 1) % len(STYLE["trans"])] if idx > 0 else None
    tr_out = STYLE["trans"][idx % len(STYLE["trans"])] if not last else None
    flashes = [0.0] if idx == 1 else []
    for i in range(n):
        t = i / FPS
        gt = t0 + t
        STYLE["_gt"] = gt
        fr = fn(sp, t, gt, total).convert("RGB")
        fr = post(fr, sp, t, gt, total)
        fr = flash(fr, t, flashes, 0.25)
        if tr_in: fr = transition(tr_in, fr, t, dur, True, False)
        if tr_out: fr = transition(tr_out, fr, t, dur, False, True)
        p.stdin.write(fr.tobytes())
    p.stdin.close()
    if p.wait() != 0: raise SystemExit("ffmpeg failed")
    os.replace(tmp, path)

def main():
    ep = json.load(open(sys.argv[1])); out = sys.argv[2]
    st = setup_style(ep)
    scenes = ep["scenes"] + [{"type": "outro", "dur": 4.0, **ep.get("outro", {})}]
    for i, s in enumerate(scenes): s["_idx"] = i; s["_last"] = (i == len(scenes) - 1)
    total = sum(s["dur"] for s in scenes)
    starts, t0 = [], 0.0
    for s in scenes: starts.append(t0); t0 += s["dur"]
    drop = starts[1]; end = starts[-1]
    ci = [i for i, s in enumerate(scenes) if s["type"] in ("calc", "stat")]
    if ci:
        c = ci[0]
        brk = (starts[c], starts[c] + (0.8 + len(scenes[c]["rows"]) * 1.0 + 0.4 + 1.0 if scenes[c]["type"] == "calc" else 1.6))
    else:
        brk = (end, end)
    st.update(drop=drop, end=end, brk=brk)
    print("STYLE", json.dumps({k: st[k] for k in ("seed", "theme", "genre", "bpm", "key", "minor", "prog", "trans", "text_mode", "hook_mode", "motif")}))
    only = sys.argv[3] if len(sys.argv) > 3 else None   # "preview" -> stills only
    if only == "preview":
        for i, s in enumerate(scenes):
            tt = s["dur"] - 0.35 if not s["_last"] else s["dur"] - 0.1
            STYLE["_gt"] = starts[i] + tt
            fr = SCENES[s["type"]](s, tt, starts[i] + tt, total).convert("RGB")
            post(fr, s, tt, starts[i] + tt, total).save(f"{out}_scene{i}.jpg", quality=88)
        return
    work = tempfile.mkdtemp(prefix="dkv_")
    files = []
    for i, s in enumerate(scenes):
        f = os.path.join(work, f"s{i:02d}.mp4"); render_scene(SCENES[s["type"]], s, starts[i], total, f); files.append(f)
    with open(os.path.join(work, "list.txt"), "w") as fl:
        for f in files: fl.write(f"file '{f}'\n")
    music(os.path.join(work, "m.wav"), total, starts[1:], drop, brk, end, st)
    tmp = out + ".part.mp4"
    subprocess.run(["ffmpeg", "-v", "error", "-y", "-f", "concat", "-safe", "0", "-i", os.path.join(work, "list.txt"),
                    "-i", os.path.join(work, "m.wav"), "-map", "0:v", "-map", "1:a", "-c:v", "copy",
                    "-af", "treble=g=-1.5:f=8000,volume=-1dB", "-c:a", "aac", "-b:a", "192k",
                    "-movflags", "+faststart", "-shortest", tmp], check=True)
    os.replace(tmp, out)
    print("OK", out, f"{total:.1f}s")

if __name__ == "__main__":
    main()
